UpdateSchema "C:\Users\carlos.riasco\Documents\BRYAN TORRES\2. Capa normativa\Actualizacion Catalogo\CatalogoOT.gdb\b_NormadelSuelo\ClasificacionSuelo" "<operationSequence><workflow><AddAttributeRule><rule_name>Sincronizar_RuleID_11</rule_name><rule_type>CALCULATION</rule_type><expression>// 1. Obtener la descripción textual (nombre) de lo que se seleccionó
var nombreSeleccionado = DomainName($feature, 'Tipo_Clasificacion_Suelo');

// Si el campo está vacío, no devolvemos nada
if (IsEmpty(nombreSeleccionado)) { 
    return null; 
}

// 2. Acceder al objeto del dominio vinculado al campo RuleID
// Esto nos permite leer la lista de "Nombre" y "Código" de ese campo específico
var dom = Domain($feature, 'RuleID');
var listaOpciones = dom.codedValues;

// 3. Buscar el nombre coincidente en el segundo dominio
for (var i in listaOpciones) {
    // Comparamos el nombre seleccionado con los nombres en el dominio de RuleID
    if (listaOpciones[i].name == nombreSeleccionado) {
        // Al encontrar la coincidencia por nombre, devolvemos el CÓDIGO de ese dominio
        return listaOpciones[i].code;
    }
}

// Si por alguna razón los nombres no coinciden exactamente, devuelve nulo o un valor por defecto
return null;</expression><is_editable>True</is_editable><triggering_events_insert>True</triggering_events_insert><triggering_events_delete>False</triggering_events_delete><triggering_events_update>True</triggering_events_update><field_name>RuleID</field_name><exclude_from_client_eval>False</exclude_from_client_eval><batch>False</batch><severity>-1</severity><category>4294967295</category></AddAttributeRule><ReorderAttributeRule><rule_name>Sincronizar_RuleID_11</rule_name><evaluation_order>1</evaluation_order></ReorderAttributeRule></workflow></operationSequence>"

UpdateSchema "C:\Users\carlos.riasco\Documents\BRYAN TORRES\2. Capa normativa\Actualizacion Catalogo\CatalogoOT.gdb\b_NormadelSuelo\ClasificacionSuelo" "<operationSequence><workflow><AddAttributeRule><rule_name>Sincronizar_RuleID_CS</rule_name><rule_type>CALCULATION</rule_type><expression>// 1. Obtener la descripción textual del campo de origen
var nombreSeleccionado = DomainName($feature, 'Tipo_Clasificacion_Suelo');

if (IsEmpty(nombreSeleccionado)) { 
    return null; 
}

// 2. Mapeo de excepciones: Estandarizamos el nombre a buscar
// Aquí corregimos las diferencias entre "Tipo_Clasificacion_Suelo" y "RuleID"
var nombreBuscar = nombreSeleccionado;

if (nombreSeleccionado == 'Expansion_Urbana' ) {
    nombreBuscar = 'Expansión urbana';
}

// 3. Acceder al objeto del dominio del RuleID 
var dom = Domain($feature, 'RuleID'); 
var listaOpciones = dom.codedValues;

// 4. Buscar el nombre (ya estandarizado) en la lista del RuleID
for (var i in listaOpciones) {
    if (listaOpciones[i].name == nombreBuscar) {
        // Devolvemos el código correcto
        return listaOpciones[i].code;
    }
}

return null;</expression><is_editable>True</is_editable><triggering_events_insert>True</triggering_events_insert><triggering_events_delete>False</triggering_events_delete><triggering_events_update>True</triggering_events_update><field_name>RuleID</field_name><exclude_from_client_eval>False</exclude_from_client_eval><batch>False</batch><severity>-1</severity><category>2147483647</category></AddAttributeRule><ReorderAttributeRule><rule_name>Sincronizar_RuleID_CS</rule_name><evaluation_order>2</evaluation_order></ReorderAttributeRule></workflow><workflow><DeleteAttributeRule><rule_name>Sincronizar_RuleID_11</rule_name><rule_type>CALCULATION</rule_type></DeleteAttributeRule></workflow></operationSequence>"
